pub(super) fn nodal_gradient(matrix: DMat3) -> [DVec3; 4] {
    [
        -(matrix.x_axis + matrix.y_axis + matrix.z_axis),
        matrix.x_axis,
        matrix.y_axis,
        matrix.z_axis,
    ]
}

pub(super) fn solve_implicit(
        &self,
        x: &mut Vec<DVec3>,
        predicted: &[DVec3],
        frame: Frame,
        dt: f64,
    ) -> Result<(), TissueError> {
        for _ in 0..self.material.iterations {
            let system = self.linearize(x, predicted, frame, dt);
            if dot(&system.gradient, &system.gradient) < 1e-16 {
                break;
            }
            let delta = system.direction();
            let slope = dot(&system.gradient, &delta);
            *x = self.descend(x, &delta, slope, |x| {
                self.objective(x, predicted, frame, dt)
            })?;
        }
        Ok(())
    }fn dot(a: &[DVec3], b: &[DVec3]) -> f64fn direction(&self) -> Vec<DVec3>fn descend( &self, x: &[DVec3], delta: &[DVec3], slope: f64, objective: impl Fn(&[DVec3]) -> f64, ) -> Result<Vec<DVec3>, TissueError>fn linearize(&self, x: &[DVec3], predicted: &[DVec3], frame: Frame, dt: f64) -> Systemfn objective(&self, x: &[DVec3], predicted: &[DVec3], frame: Frame, dt: f64) -> f64

pub fn equilibrate(
        &mut self,
        gravity: DVec3,
        max_iterations: usize,
    ) -> Result<f64, TissueError> {
        if !gravity.is_finite() || !(1..=4096).contains(&max_iterations) {
            return Err(TissueError::InvalidInput("equilibrium parameters"));
        }
        let mut x = self.positions.clone();
        let objective = |x: &[DVec3]| {
            self.objective(x, &self.positions, self.frame, f64::INFINITY)
                - x.iter()
                    .zip(&self.positions)
                    .zip(&self.masses)
                    .map(|((x, p), m)| m * gravity.dot(*x - *p))
                    .sum::<f64>()
        };
        for _ in 0..max_iterations {
            let mut system = self.linearize(&x, &self.positions, self.frame, f64::INFINITY);
            for (i, g) in system.gradient.iter_mut().enumerate() {
                if self.inverse_mass[i] > 0.0 {
                    *g -= self.masses[i] * gravity;
                }
            }
            let residual = system
                .gradient
                .iter()
                .map(|g| g.length())
                .fold(0.0, f64::max);
            if residual < 2e-5 {
                self.positions = x;
                self.velocities.fill(DVec3::ZERO);
                return Ok(residual);
            }
            let delta = system.direction();
            x = self.descend(&x, &delta, dot(&system.gradient, &delta), &objective)?;
        }
        Err(TissueError::InvalidInput("equilibrium did not converge"))
    }type Err = anyhow::Errorfn dot(a: &[DVec3], b: &[DVec3]) -> f64fn direction(&self) -> Vec<DVec3>fn descend( &self, x: &[DVec3], delta: &[DVec3], slope: f64, objective: impl Fn(&[DVec3]) -> f64, ) -> Result<Vec<DVec3>, TissueError>fn linearize(&self, x: &[DVec3], predicted: &[DVec3], frame: Frame, dt: f64) -> Systemfn objective(&self, x: &[DVec3], predicted: &[DVec3], frame: Frame, dt: f64) -> f64
